/// <summary>
/// Modify field properties based on field values
/// </summary>
private void modifyFieldProperties()
{
    METSiteControllingAndSubordinateSetup siteControllingAndSubordinateSetup = this.cursor();


    if (siteControllingAndSubordinateSetup.IsControllingSite == NoYes::No)
    {
        this.object(fieldNum(METSiteControllingAndSubordinateSetup, ControllingSiteId)).mandatory(true);
        this.object(fieldNum(METSiteControllingAndSubordinateSetup, ControllingSiteId)).allowEdit(true);
    }
    else
    {
        this.object(fieldNum(METSiteControllingAndSubordinateSetup, ControllingSiteId)).mandatory(false);
        this.object(fieldNum(METSiteControllingAndSubordinateSetup, ControllingSiteId)).allowEdit(false);
    }


}

/// <summary>
/// METSiteControllingAndSubOrdinateSetup selection changed
/// </summary>
public void selectionChanged()
{
    next selectionChanged();
    this.modifyFieldProperties();

}
